                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_mentor_advice", conditions = N(), end = false },
                    new DialogueNodeData { id = "after_obey", speaker = "", text = "Your mentor nods. The lesson sits right.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor_advice", "obey", 0)), end = false },
                    new DialogueNodeData { id = "after_defy", speaker = "", text = "Your mentor says nothing. The silence is a lesson too.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor_advice", "defy", 0)), end = false },
