            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c1_first_echo_intro",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "At the Spire's root the light has pooled into a shape - almost a person, never finished.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
