            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c1_first_echo_fallen",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "The First Echo comes apart in slow ribbons. Where it stood, the floor is warm.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "", nextId = "", branchPrefix = "mentorword", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "mentorword_v0", speaker = "Kael", text = "That's how it's done. Hit it first. Every time.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "mentorword_v1", speaker = "Sister Odalys", text = "You're shaking. Good - it means you were there for all of it. Breathe.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "mentorword_v2", speaker = "Warden Bran", text = "You held. Whatever comes next - you held here first.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "mentorword", speaker = "", text = "", nextId = "n2", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n2", speaker = "", text = "Above you, very far up, something in the Spire begins - quietly - to sing.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
