            content.graphs.Add(new DialogueGraphData
            {
                id = "g_i2_archivist",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "The Archivist", text = "Ari. Twenty years old, four since the Fracture. I have kept the count: your echoes, your codex, your debts.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "", nextId = "", branchPrefix = "recap", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "recap_v0", speaker = "The Archivist", text = "Kael taught you to hit first. Your Ember runs hot; the Choir marks you as a threat, not a harvest.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "recap_v1", speaker = "The Archivist", text = "Odalys taught you to breathe first. Your Tide runs deep; the relief lines say your name like a prayer.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "recap_v2", speaker = "The Archivist", text = "Bran taught you to stand first. Your Stone runs steady; the Wardens count you as one of their own.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "recap", speaker = "", text = "", nextId = "n2", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n2", speaker = "The Archivist", text = "The Choir holds three places in Vessa. You may take back one. Choose the shape of your becoming.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_c2_path", conditions = N(), end = false },
