                    new DialogueNodeData { id = "after_sanctuary", speaker = "The Archivist", text = "The Sanctuary. A defence. Hold what the Choir wants to drown.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_c2_path", "sanctuary", 0)), end = false },
                    new DialogueNodeData { id = "after_long_wall", speaker = "The Archivist", text = "The Long Wall. A line. Stand where the city ends and the Choir begins.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_c2_path", "long_wall", 0)), end = false },
                    new DialogueNodeData { id = "after", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c2_mentor_interlude",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "", nextId = "", branchPrefix = "c2m", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "c2m_v0", speaker = "Kael", text = "You listened under the Spire. Keep listening: the Docks fall to whoever is willing to burn the pier. Are you?", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_obeyed", "1", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "c2m_v1", speaker = "Kael", text = "You didn't listen under the Spire. It worked. It won't always. The Docks are yours if you want them - my advice, or not.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "c2m_v2", speaker = "Sister Odalys", text = "You listened under the Spire. The Sanctuary holds the last clean water in the Reaches. If it falls, so do the relief lines.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_obeyed", "1", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "c2m_v3", speaker = "Sister Odalys", text = "You went your own way under the Spire - and you're alive. Good. The Sanctuary needs someone who knows when not to listen.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "c2m_v4", speaker = "Warden Bran", text = "You held under the Spire like I told you. The Long Wall is longer than any of us. Hold it anyway.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_obeyed", "1", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "c2m_v5", speaker = "Warden Bran", text = "You didn't hold the way I said. You held your way. The Wall doesn't care whose way - only that it's held.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "c2m", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c2_docks_open",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "The Contested Docks: cranes stopped mid-lift, Choir graffiti on every hull, the song coming off the water in waves.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "Four arenas between the gate and the harbour master's tower. The Elite is in the tower.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
        }

