                    new DialogueNodeData { id = "after_yield", speaker = "Dax", text = "Next time. There's always a next time with you.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_dax_duel_end", "yield", 0)), end = false },
