            content.graphs.Add(new DialogueGraphData
            {
                id = "g_i3_archivist",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "The Archivist", text = "Twenty-six. Ten years since the light. I have kept the count. Look at what Vessa became while you were becoming.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "", nextId = "", branchPrefix = "market", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "market_v0", speaker = "The Archivist", text = "The Old Market is rebuilt. Stalls, lanterns, the smell of bread at dawn. They say your name there.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "market", "rebuilt", 0)), end = false },
                    new DialogueNodeData { id = "market_v1", speaker = "The Archivist", text = "The Old Market is ruined. Nobody trades there now. The Choir's graffiti has faded; nothing replaced it.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "market", "ruined", 0)), end = false },
                    new DialogueNodeData { id = "market_v2", speaker = "The Archivist", text = "The Old Market is contested still - Choir patrols by night, stallholders by day, and neither yields.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "market", "contested", 0)), end = false },
                    new DialogueNodeData { id = "market", speaker = "", text = "", nextId = "n2", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n2", speaker = "", text = "", nextId = "", branchPrefix = "docks", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "docks_v0", speaker = "The Archivist", text = "The Docks are a flooded sanctum now; the relief lines row between the cranes.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "docks", "flooded", 0)), end = false },
                    new DialogueNodeData { id = "docks_v1", speaker = "The Archivist", text = "The Docks are a fortified wall; the Wardens hold them the way you held the Long Wall.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "docks", "fortified", 0)), end = false },
                    new DialogueNodeData { id = "docks_v2", speaker = "The Archivist", text = "The Docks work again - cranes lifting, hulls scraped clean of the Choir's marks.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.WorldStateIs, "docks", "working", 0)), end = false },
                    new DialogueNodeData { id = "docks", speaker = "", text = "", nextId = "n3", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n3", speaker = "", text = "", nextId = "", branchPrefix = "mara", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "mara_v0", speaker = "The Archivist", text = "Mara is gone. The kite string is in your pocket. I counted it, once, among your items; I have stopped.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "lost", 0)), end = false },
                    new DialogueNodeData { id = "mara_v1", speaker = "The Archivist", text = "Mara is at the barricade line with her wraps on. She intends to climb the Spire with you.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "ally", 0)), end = false },
                    new DialogueNodeData { id = "mara_v2", speaker = "The Archivist", text = "Mara is alive. She runs a relief line. She still comes to the pier.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "mara", speaker = "", text = "", nextId = "n4", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n4", speaker = "", text = "", nextId = "", branchPrefix = "daxword", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "daxword_v0", speaker = "The Archivist", text = "Dax is dead. The amphitheatre is a memorial nobody visits.", nextId = "n5", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "dead", 0)), end = false },
                    new DialogueNodeData { id = "daxword_v1", speaker = "The Archivist", text = "Dax is here. He asked me, quietly, whether you would want him. I did not know what to say.", nextId = "n5", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "redeemed", 0)), end = false },
                    new DialogueNodeData { id = "daxword_v2", speaker = "The Archivist", text = "Dax holds the Reaches with a crew of the newly lit. He does not say your name; he does not need to.", nextId = "n5", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "truce", 0)), end = false },
                    new DialogueNodeData { id = "daxword_v3", speaker = "The Archivist", text = "Dax has gone up the Spire ahead of you. He is singing.", nextId = "n5", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "final_enemy", 0)), end = false },
                    new DialogueNodeData { id = "daxword_v4", speaker = "The Archivist", text = "Dax is somewhere in the city. He always is.", nextId = "n5", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "daxword", speaker = "", text = "", nextId = "n5", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n5", speaker = "The Archivist", text = "The Spire is breached. The Choirmaster is at the Fracture's heart. Whatever you are - go and be it.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_i3_shrine",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "Echo Shrine", text = "The reckoning shrine hums at the frequency of ten years.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_i3_shrine", conditions = N(), end = false },
                    new DialogueNodeData { id = "after", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_i3_hollow_shrine",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "The dark plinth has no hum. It has a pull.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_hollow_shrine", conditions = N(), end = false },
                    new DialogueNodeData { id = "after", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
        }

