            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c3_cm_transition",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "The overture breaks. In the silence you can hear the sea.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "", nextId = "", branchPrefix = "cmt", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "cmt_v0", speaker = "Kael", text = "Kid. Say the word and I'll hold it. You hit first - like I taught you.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "alive", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "cmt_v1", speaker = "Sister Odalys", text = "Breathe. If you need me to stand in front - I have stood in front before.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "alive", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "cmt_v2", speaker = "Warden Bran", text = "I'll hold it. That's what I'm for. Your call.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "alive", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "cmt_v3", speaker = "The Choirmaster", text = "No one comes for you this time, first-lit. Press, or go.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "cmt", speaker = "", text = "", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_cm_transition", conditions = N(), end = false },
                    new DialogueNodeData { id = "after_press", speaker = "The Choirmaster", text = "GOOD. Then hear the chorus.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_cm_transition", "press", 0)), end = false },
                    new DialogueNodeData { id = "after_mentor_shield", speaker = "", text = "Your mentor's last word is your name.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_cm_transition", "mentor_shield", 0)), end = false },
                    new DialogueNodeData { id = "after_refuse", speaker = "", text = "The sea is very loud.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.DecisionWas, "dec_cm_transition", "refuse", 0)), end = false },
                    new DialogueNodeData { id = "after", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c3_cm_phase2",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "", nextId = "", branchPrefix = "p2", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "p2_v0", speaker = "Dax, Final Enemy", text = "Ari. I sing now. Turns out I was always going to.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "final_enemy", 0)), end = false },
                    new DialogueNodeData { id = "p2_v1", speaker = "Mara, Turned", text = "You left me under the crane. I got up anyway. Look what got up with me.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "turned", 0)), end = false },
                    new DialogueNodeData { id = "p2_v2", speaker = "Mara", text = "Left side's mine. Don't you DARE die in front of me.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "ally", 0)), end = false },
                    new DialogueNodeData { id = "p2_v3", speaker = "Dax", text = "Right side. And Ari - we're telling everyone this one worked.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dax_fate", "redeemed", 0)), end = false },
                    new DialogueNodeData { id = "p2_v4", speaker = "The Choirmaster, Unmasked", text = "You came alone. Then hear it alone.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "p2", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c3_cm_phase3",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "", nextId = "", branchPrefix = "p3", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "p3_v0", speaker = "", text = "Phase three: a race. The Choirmaster's song is gathering the Fracture; burn faster than it can sing.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dominant", "ember", 0)), end = false },
                    new DialogueNodeData { id = "p3_v1", speaker = "", text = "Phase three: a ward. The song is reaching for the people on the lower floors; keep it off them until it breaks.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dominant", "tide", 0)), end = false },
                    new DialogueNodeData { id = "p3_v2", speaker = "", text = "Phase three: attrition. The song cannot be outrun; it can be outlasted. Stand.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dominant", "stone", 0)), end = false },
                    new DialogueNodeData { id = "p3_v3", speaker = "", text = "Phase three: a window. When the song thins, everything already breaking will break. Wait for it. Take it.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "dominant", "hollow", 0)), end = false },
                    new DialogueNodeData { id = "p3_v4", speaker = "", text = "Phase three: everything at once. You were never one thing. Neither is this.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "p3", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_c3_final_decision",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "The Choirmaster's song is over. The heart of the Fracture is open in front of you - patient as the pier, warm as the last summer.", nextId = "decide", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "decide", speaker = "", text = "", nextId = "", branchPrefix = "after", decisionId = "dec_ending", conditions = N(), end = false },
                    new DialogueNodeData { id = "after", speaker = "", text = "", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "end", speaker = "", text = "", nextId = "", branchPrefix = "", decisionId = "", conditions = N(), end = true }
                }
            });
            content.graphs.Add(new DialogueGraphData
            {
                id = "g_ep_epilogue",
                nodes = new List<DialogueNodeData>
                {
                    new DialogueNodeData { id = "n0", speaker = "The Archivist", text = "Vessa, after. I kept the count to the end. This is how it reads.", nextId = "n1", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n1", speaker = "", text = "", nextId = "", branchPrefix = "ending", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "ending_v0", speaker = "The Archivist", text = "ASHEN CROWN. The Choir is ash and so is the Spire's crown. Vessa is safe. Vessa locks its doors when you walk by. You do not mind. You tell yourself you do not mind.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "ashen_crown", 0)), end = false },
                    new DialogueNodeData { id = "ending_v1", speaker = "The Archivist", text = "TIDE'S EMBRACE. The light went into the sea and the sea forgave it. Relief lines became a harbour; a harbour became a city again. Mara's kite flies over the pier every summer. You hold the string.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "tides_embrace", 0)), end = false },
                    new DialogueNodeData { id = "ending_v2", speaker = "The Archivist", text = "THE UNMOVED. The Fracture is stone now and the districts you saved stand on it. The Wardens carve your name on the Long Wall. You did not move. Vessa learned it could stop moving too.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "the_unmoved", 0)), end = false },
                    new DialogueNodeData { id = "ending_v3", speaker = "The Archivist", text = "HOLLOW THRONE. The Spire collapsed and something sits where it stood. It wears your face and sings in Dax's voice. Vessa is very quiet. I am the only one who still says your name, and I am afraid of it.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "hollow_throne", 0)), end = false },
                    new DialogueNodeData { id = "ending_v4", speaker = "The Archivist", text = "BALANCE. The light stays, shared and watched. Mara watches the water; Dax watches the Reaches; you watch them both. Nothing ended. That was the hardest thing anyone in Vessa ever did.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "balance", 0)), end = false },
                    new DialogueNodeData { id = "ending_v5", speaker = "The Archivist", text = "MARTYR'S DAWN. You closed it from the inside. The first clean dawn in ten years came up over a city that did not yet know what it cost. They know now. They come to the pier.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "martyrs_dawn", 0)), end = false },
                    new DialogueNodeData { id = "ending_v6", speaker = "The Archivist", text = "THE LONG WAY HOME. You walked down. The song went on, then faltered, then stopped on its own - years later, with no one to hear it. You were at the pier. You were always going to be at the pier.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "ending", "long_way_home", 0)), end = false },
                    new DialogueNodeData { id = "ending_v7", speaker = "The Archivist", text = "The count does not read. That should not be possible.", nextId = "n2", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "ending", speaker = "", text = "", nextId = "n2", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n2", speaker = "", text = "", nextId = "", branchPrefix = "epmara", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "epmara_v0", speaker = "The Archivist", text = "Mara: Lost. The kite string is still in your pocket.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "lost", 0)), end = false },
                    new DialogueNodeData { id = "epmara_v1", speaker = "The Archivist", text = "Mara: Turned, and unmade on the Spire. Vessa does not say her name near you.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "turned", 0)), end = false },
                    new DialogueNodeData { id = "epmara_v2", speaker = "The Archivist", text = "Mara: Ally. She fought beside you to the end, and she still comes to the pier.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "ally", 0)), end = false },
                    new DialogueNodeData { id = "epmara_v3", speaker = "The Archivist", text = "Mara: alive, and a civilian. The relief lines run at dawn; she runs them.", nextId = "n3", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "epmara", speaker = "", text = "", nextId = "n3", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "n3", speaker = "", text = "", nextId = "", branchPrefix = "epmentor", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "epmentor_v0", speaker = "The Archivist", text = "Kael: Fallen. The memorial is a coat, folded, on the Spire steps. Nobody has moved it.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "fallen", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "kael", 0)), end = false },
                    new DialogueNodeData { id = "epmentor_v1", speaker = "The Archivist", text = "Sister Odalys: Fallen. The Sanctuary keeps a wet hem in a glass case, and the relief lines sing her name.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "fallen", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "odalys", 0)), end = false },
                    new DialogueNodeData { id = "epmentor_v2", speaker = "The Archivist", text = "Warden Bran: Fallen. He held a door for six hours once. On the Spire he held one for you.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "fallen", 0), Cd(ConditionType.DecisionWas, "dec_mentor", "bran", 0)), end = false },
                    new DialogueNodeData { id = "epmentor_v3", speaker = "The Archivist", text = "Your mentor: Estranged. They were not on the Spire. They heard how it ended from someone else.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "estranged", 0)), end = false },
                    new DialogueNodeData { id = "epmentor_v4", speaker = "The Archivist", text = "Your mentor: Alive. They stood in phase two and they stand at the pier now, not saying much. They never did.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mentor_fate", "alive", 0)), end = false },
                    new DialogueNodeData { id = "epmentor_v5", speaker = "The Archivist", text = "Your mentor: unrecorded. The count has a gap where a name should be.", nextId = "n4", branchPrefix = "", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "epmentor", speaker = "", text = "", nextId = "n4", branchPrefix = "", decisionId = "", conditions = N(), end = false },
