                {
                    new DialogueNodeData { id = "n0", speaker = "", text = "", nextId = "", branchPrefix = "c3m", decisionId = "", conditions = N(), end = false },
                    new DialogueNodeData { id = "c3m_v0", speaker = "Mara", text = "Ten years. Kite string's still on my wrist. Let's go and finish the song, Ari.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.FlagIs, "mara_fate", "ally", 0)), end = false },
                    new DialogueNodeData { id = "c3m_v1", speaker = "Mara", text = "I'll be at the barricade when you come down. I'll be at the pier after. I'm always going to be somewhere you can find.", nextId = "end", branchPrefix = "", decisionId = "", conditions = L(Cd(ConditionType.BondAtLeast, "mara", "", 50)), end = false },
                    new DialogueNodeData { id = "c3m_v2", speaker = "Mara", text = "Go on. Whatever you are now - go and be it. I'll hold the line down here.", nextId = "end", branchPrefix = "", decisionId = "", conditions = N(), end = false },
